-- Engapp v0.2 İP2: word levels (CEFR A1–C2).
--
-- Reference data (CC BY-SA / attribution sources) lives in its own tables, apart from the
-- AI-built shared lexicon: ref_word_levels (CEFR-J + Octanove C1/C2, one row per lemma, part of
-- speech and list), ref_word_freq (wordfreq Zipf values) and ref_sources (versions, licences,
-- checksums). The rows are loaded by 20261021001200_ref_word_data.sql, generated by
-- scripts/build-levels.ts.
--
-- The level of a lexicon sense is decided by one rule, in TypeScript
-- (supabase/functions/_shared/level.ts, also used by the app): the list level (with the
-- Turkish-learner correction), else the AI guess bounded by frequency, else frequency only.
-- The edge functions store it when they insert a sense; the nightly level job
-- (scripts/system-jobs.ts, .github/workflows/level-jobs.yml) fills older senses and
-- re-resolves them when the reference data changes. Clients get the columns through the
-- lexicon_entries view (lexicon_pull / lexicon_get), so nothing new is synced for them.
--
-- notes.level_override: the user's own level for a word. A synced column of their note; it
-- applies only to them.

-- ---------------------------------------------------------------------------
-- helpers
-- ---------------------------------------------------------------------------

create or replace function public.cefr_rank(p_level text)
returns integer
language sql
immutable
parallel safe
set search_path = ''
as $$
  select array_position(array['A1', 'A2', 'B1', 'B2', 'C1', 'C2'], p_level) - 1
$$;

revoke all on function public.cefr_rank(text) from public, anon;
grant execute on function public.cefr_rank(text) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- reference tables (read by signed-in users, written only by migrations / the service role)
-- ---------------------------------------------------------------------------

create table public.ref_sources (
  key text primary key check (key ~ '^[a-z0-9_]{1,40}$'),
  name text not null check (char_length(name) <= 200),
  version text not null check (char_length(version) <= 40),
  license text not null check (char_length(license) <= 500),
  url text not null check (char_length(url) <= 500),
  sha256 text not null check (sha256 ~ '^[0-9a-f]{64}$'),
  rows integer not null check (rows >= 0),
  -- Frequency source only: it holds every word at or above this Zipf value, so a plain word
  -- missing from ref_word_freq is rarer (level.ts FreqCoverage).
  coverage_min_zipf numeric(4, 2) check (coverage_min_zipf between 0 and 9),
  loaded_at timestamptz not null default now()
);

create table public.ref_word_levels (
  lemma_norm text not null check (
    char_length(lemma_norm) between 1 and 120 and lemma_norm = lower(lemma_norm)),
  pos text not null check (pos in (
    'noun', 'verb', 'adjective', 'adverb', 'preposition', 'conjunction', 'pronoun',
    'determiner', 'interjection', 'other')),
  cefr text not null check (cefr in ('A1', 'A2', 'B1', 'B2', 'C1', 'C2')),
  source text not null check (source in ('cefrj', 'octanove')),
  source_version text not null check (char_length(source_version) <= 40),
  -- Turkish-learner correction (prompt level-tr-v1), made once per entry by the level job.
  -- tr_checked_at null: not checked yet. tr_base_cefr: the list level that was checked; when
  -- a new list version changes `cefr`, the correction no longer applies and is redone.
  -- tr_cefr null: the list level is right for a Turkish speaker.
  tr_checked_at timestamptz,
  tr_base_cefr text check (tr_base_cefr in ('A1', 'A2', 'B1', 'B2', 'C1', 'C2')),
  tr_cefr text check (tr_cefr in ('A1', 'A2', 'B1', 'B2', 'C1', 'C2')),
  tr_reason text check (char_length(tr_reason) between 1 and 120),
  tr_model text check (char_length(tr_model) <= 100),
  tr_prompt_version text check (char_length(tr_prompt_version) <= 40),
  primary key (lemma_norm, pos, source),
  check ((tr_checked_at is null) = (tr_base_cefr is null)),
  check (tr_cefr is null or tr_base_cefr is not null),
  -- The AI may move a list level by one step at most (also clamped in code).
  check (tr_cefr is null or abs(public.cefr_rank(tr_cefr) - public.cefr_rank(tr_base_cefr)) = 1),
  check ((tr_cefr is null) = (tr_reason is null))
);

create index ref_word_levels_pending on public.ref_word_levels (lemma_norm) where tr_checked_at is null;

create table public.ref_word_freq (
  lemma_norm text primary key check (
    char_length(lemma_norm) between 1 and 120 and lemma_norm = lower(lemma_norm)),
  zipf numeric(4, 2) not null check (zipf between 0 and 9)
);

alter table public.ref_sources enable row level security;
alter table public.ref_word_levels enable row level security;
alter table public.ref_word_freq enable row level security;
revoke all on table public.ref_sources, public.ref_word_levels, public.ref_word_freq from anon, authenticated;
grant select on table public.ref_sources, public.ref_word_levels, public.ref_word_freq to authenticated;
create policy "reference: read for signed-in users" on public.ref_sources
  for select to authenticated using (true);
create policy "reference: read for signed-in users" on public.ref_word_levels
  for select to authenticated using (true);
create policy "reference: read for signed-in users" on public.ref_word_freq
  for select to authenticated using (true);
-- No write policies: only migrations and the service role write reference data.

-- ---------------------------------------------------------------------------
-- lexicon columns
-- ---------------------------------------------------------------------------

alter table public.lexicon_terms
  add column zipf numeric(4, 2) check (zipf between 0 and 9);

alter table public.lexicon_senses
  add column cefr text check (cefr in ('A1', 'A2', 'B1', 'B2', 'C1', 'C2')),
  add column cefr_source text check (cefr_source in ('cefrj', 'octanove', 'ai', 'freq', 'words')),
  -- List level before the Turkish-learner correction (list sources only).
  add column cefr_list text check (cefr_list in ('A1', 'A2', 'B1', 'B2', 'C1', 'C2')),
  -- Short Turkish reason of the correction ("Türkçede 'televizyon'").
  add column cefr_reason_tr text check (char_length(cefr_reason_tr) between 1 and 120),
  -- The model's own guess (extract-v3 / enrich-v2 / level-guess-v1), kept so the level can be
  -- resolved again when the reference data changes. Never shown as the level by itself.
  add column cefr_guess text check (cefr_guess in ('A1', 'A2', 'B1', 'B2', 'C1', 'C2')),
  -- When the level job last asked the model for a guess (any outcome): asked once only.
  add column cefr_guess_at timestamptz,
  add constraint lexicon_senses_cefr_pair check ((cefr is null) = (cefr_source is null)),
  add constraint lexicon_senses_cefr_tr check (
    cefr_reason_tr is null or (cefr_source in ('cefrj', 'octanove') and cefr_list is not null));

create index lexicon_senses_level_pending on public.lexicon_senses (id) where cefr is null;

-- A corrected lemma or a new frequency must reach devices that pull senses by cursor.
create or replace function public.tg_lexicon_term_touch_senses()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (new.lemma, new.term_type, new.zipf) is distinct from (old.lemma, old.term_type, old.zipf) then
    update public.lexicon_senses set updated_at = now() where term_id = new.id;
  end if;
  return new;
end;
$$;

-- Flat LexiconSense rows: the v0.1 columns, then (new, at the end) the level columns.
create or replace view public.lexicon_entries
with (security_invoker = true)
as
select
  s.id,
  s.term_id,
  t.lemma,
  t.lemma_norm,
  t.term_type,
  s.pos,
  s.gloss_en,
  s.meaning_tr,
  s.ipa,
  (extract(epoch from greatest(s.updated_at, t.updated_at)) * 1000)::bigint as updated_at,
  s.server_seq,
  s.cefr,
  s.cefr_source,
  s.cefr_list,
  s.cefr_reason_tr,
  t.zipf::double precision as zipf
from public.lexicon_senses s
join public.lexicon_terms t on t.id = s.term_id;

revoke all on public.lexicon_entries from anon, authenticated;
grant select on public.lexicon_entries to authenticated;

-- lexicon_find (used by the AI functions): the level columns too, so a lexicon hit returns
-- complete entries (the client caches what it gets).
create or replace function public.lexicon_find(p_norms text[], p_max_senses integer default 12)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'term_id', t.id,
      'lemma', t.lemma,
      'lemma_norm', t.lemma_norm,
      'term_type', t.term_type,
      'zipf', t.zipf::double precision,
      'senses', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', s.id,
          'pos', s.pos,
          'gloss_en', s.gloss_en,
          'gloss_key', s.gloss_key,
          'meaning_tr', s.meaning_tr,
          'ipa', s.ipa,
          'cefr', s.cefr,
          'cefr_source', s.cefr_source,
          'cefr_list', s.cefr_list,
          'cefr_reason_tr', s.cefr_reason_tr,
          'updated_at', (extract(epoch from s.updated_at) * 1000)::bigint
        ) order by s.created_at, s.id)
        from (
          select * from public.lexicon_senses s2
          where s2.term_id = t.id
          order by s2.created_at, s2.id
          limit greatest(1, least(p_max_senses, 50))
        ) s
      ), '[]'::jsonb)
    ) order by t.lemma_norm), '[]'::jsonb)
  from public.lexicon_terms t
  where t.lemma_norm = any (p_norms[1:5000])
$$;

-- p_items: [{lemma, lemma_norm, term_type, pos, gloss_en, gloss_key, meaning_tr, ipa, model,
--            zipf?, cefr?, cefr_source?, cefr_list?, cefr_reason_tr?, cefr_guess?}]
-- Returns, in input order: [{term_id, sense_id, term_created, sense_created}].
-- Same as 20261021001000 plus the level columns: a new term stores its Zipf value (an
-- existing term without one gets it), a new sense stores the level the edge function
-- resolved (level.ts). A cefr_guess key (even null) means the model was asked, so the level
-- job does not ask again (cefr_guess_at). An existing sense is never changed here.
create or replace function public.lexicon_upsert(p_items jsonb)
returns jsonb
language plpgsql
volatile
security invoker
set search_path = ''
as $$
declare
  item jsonb;
  v_term_id uuid;
  v_sense_id uuid;
  v_term_created boolean;
  v_sense_created boolean;
  v_zipf numeric;
  out jsonb := '[]'::jsonb;
begin
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 200 then
    raise exception 'p_items must be an array of at most 200 items' using errcode = '22023';
  end if;

  -- Serialise lexicon writers before reading (tg_stamp_lexicon_row takes the same lock).
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('engapp.lexicon', 0));

  for item in select value from jsonb_array_elements(p_items) loop
    v_zipf := nullif(item ->> 'zipf', '')::numeric;
    insert into public.lexicon_terms (lemma, lemma_norm, term_type, zipf)
    values (item ->> 'lemma', item ->> 'lemma_norm', item ->> 'term_type', v_zipf)
    on conflict (lemma_norm) do nothing
    returning id into v_term_id;
    v_term_created := v_term_id is not null;
    if v_term_id is null then
      select id into strict v_term_id from public.lexicon_terms where lemma_norm = item ->> 'lemma_norm';
      if v_zipf is not null then
        update public.lexicon_terms set zipf = v_zipf where id = v_term_id and zipf is null;
      end if;
    end if;

    v_sense_id := null;
    v_sense_created := false;
    if item ? 'gloss_key' and item ->> 'gloss_key' is not null then
      -- The same gloss_key: that row.
      select id into v_sense_id from public.lexicon_senses
      where term_id = v_term_id and pos = item ->> 'pos' and gloss_key = item ->> 'gloss_key';
      -- Else the same meaning, worded differently in English: the oldest such row.
      if v_sense_id is null then
        select s.id into v_sense_id from public.lexicon_senses s
        where s.term_id = v_term_id
          and s.pos = item ->> 'pos'
          and public.lexicon_meaning_alts(s.meaning_tr) && public.lexicon_meaning_alts(item ->> 'meaning_tr')
        order by s.created_at, s.id
        limit 1;
      end if;
      if v_sense_id is null then
        insert into public.lexicon_senses (
          term_id, pos, gloss_en, gloss_key, meaning_tr, ipa, created_by_model,
          cefr, cefr_source, cefr_list, cefr_reason_tr, cefr_guess, cefr_guess_at)
        values (
          v_term_id, item ->> 'pos', item ->> 'gloss_en', item ->> 'gloss_key',
          item ->> 'meaning_tr', nullif(item ->> 'ipa', ''), item ->> 'model',
          nullif(item ->> 'cefr', ''), nullif(item ->> 'cefr_source', ''),
          nullif(item ->> 'cefr_list', ''), nullif(item ->> 'cefr_reason_tr', ''),
          nullif(item ->> 'cefr_guess', ''),
          case when item ? 'cefr_guess' then pg_catalog.now() end
        )
        on conflict (term_id, pos, gloss_key) do nothing
        returning id into v_sense_id;
        v_sense_created := v_sense_id is not null;
        if v_sense_id is null then
          select id into strict v_sense_id from public.lexicon_senses
          where term_id = v_term_id and pos = item ->> 'pos' and gloss_key = item ->> 'gloss_key';
        end if;
      end if;
    end if;

    out := out || jsonb_build_array(jsonb_build_object(
      'term_id', v_term_id,
      'sense_id', v_sense_id,
      'term_created', v_term_created,
      'sense_created', v_sense_created
    ));
  end loop;
  return out;
end;
$$;

revoke all on function public.lexicon_upsert(jsonb) from public, anon, authenticated;
grant execute on function public.lexicon_upsert(jsonb) to service_role;

-- ---------------------------------------------------------------------------
-- level data for the rule (service role: edge functions and the level job)
-- ---------------------------------------------------------------------------

-- Reference data of up to 2000 lemmas: {min_zipf, rows: [{lemma_norm, zipf, refs: [{pos,
-- cefr, source, tr_cefr, tr_reason}]}]}. min_zipf: the frequency data's coverage (null while
-- no frequency data is loaded). A correction is returned only while the list level is the
-- one it was made for. Lemmas without any data are left out.
create or replace function public.level_refs(p_lemmas text[])
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
  with l as (select distinct unnest(p_lemmas[1:2000]) as lemma_norm)
  select jsonb_build_object(
    'min_zipf', (select s.coverage_min_zipf::double precision from public.ref_sources s
                  where s.key = 'wordfreq' and exists (select 1 from public.ref_word_freq)),
    'rows', coalesce(jsonb_agg(jsonb_build_object(
    'lemma_norm', l.lemma_norm,
    'zipf', f.zipf::double precision,
    'refs', coalesce((
      select jsonb_agg(jsonb_build_object(
        'pos', r.pos, 'cefr', r.cefr, 'source', r.source,
        'tr_cefr', case when r.tr_base_cefr = r.cefr then r.tr_cefr end,
        'tr_reason', case when r.tr_base_cefr = r.cefr then r.tr_reason end
      ) order by r.source, r.pos)
      from public.ref_word_levels r where r.lemma_norm = l.lemma_norm), '[]'::jsonb)
  ) order by l.lemma_norm), '[]'::jsonb))
  from l
  left join public.ref_word_freq f on f.lemma_norm = l.lemma_norm
  where f.lemma_norm is not null
     or exists (select 1 from public.ref_word_levels r where r.lemma_norm = l.lemma_norm)
$$;

revoke all on function public.level_refs(text[]) from public, anon, authenticated;
grant execute on function public.level_refs(text[]) to service_role;

-- Lexicon senses in id order after p_after (keyset paging), for the level job:
-- [{id, term_id, lemma_norm, term_type, pos, gloss_en, zipf, cefr, cefr_source, cefr_list,
--   cefr_reason_tr, cefr_guess, cefr_guess_at}].
create or replace function public.level_senses(p_after uuid default null, p_limit integer default 1000)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', s.id, 'term_id', s.term_id, 'lemma_norm', t.lemma_norm, 'term_type', t.term_type,
    'pos', s.pos, 'gloss_en', s.gloss_en, 'zipf', t.zipf::double precision,
    'cefr', s.cefr, 'cefr_source', s.cefr_source, 'cefr_list', s.cefr_list,
    'cefr_reason_tr', s.cefr_reason_tr, 'cefr_guess', s.cefr_guess,
    'cefr_guess_at', s.cefr_guess_at
  ) order by s.id), '[]'::jsonb)
  from (
    select * from public.lexicon_senses
    where p_after is null or id > p_after
    order by id
    limit least(greatest(coalesce(p_limit, 1000), 1), 5000)
  ) s
  join public.lexicon_terms t on t.id = s.term_id
$$;

revoke all on function public.level_senses(uuid, integer) from public, anon, authenticated;
grant execute on function public.level_senses(uuid, integer) to service_role;

-- Stores resolved levels. p_senses: [{id, cefr, cefr_source, cefr_list, cefr_reason_tr,
-- cefr_guess?, guess_asked?: true}], p_terms: [{id, zipf}]. Only rows that change are
-- written (each write moves the row's lexicon cursor, so devices pull it). Returns the
-- number of senses and terms changed.
create or replace function public.lexicon_set_levels(p_senses jsonb, p_terms jsonb default '[]'::jsonb)
returns jsonb
language plpgsql
volatile
security invoker
set search_path = ''
as $$
declare
  v_senses integer := 0;
  v_terms integer := 0;
begin
  if jsonb_typeof(p_senses) <> 'array' or jsonb_array_length(p_senses) > 2000
     or jsonb_typeof(p_terms) <> 'array' or jsonb_array_length(p_terms) > 2000 then
    raise exception 'at most 2000 senses and 2000 terms per call' using errcode = '22023';
  end if;

  update public.lexicon_terms t
     set zipf = (i ->> 'zipf')::numeric
    from jsonb_array_elements(p_terms) i
   where t.id = (i ->> 'id')::uuid
     and t.zipf is distinct from (i ->> 'zipf')::numeric;
  get diagnostics v_terms = row_count;

  update public.lexicon_senses s
     set cefr = nullif(i ->> 'cefr', ''),
         cefr_source = nullif(i ->> 'cefr_source', ''),
         cefr_list = nullif(i ->> 'cefr_list', ''),
         cefr_reason_tr = nullif(i ->> 'cefr_reason_tr', ''),
         cefr_guess = case when i ? 'cefr_guess' then nullif(i ->> 'cefr_guess', '') else s.cefr_guess end,
         cefr_guess_at = case when (i ->> 'guess_asked')::boolean then now() else s.cefr_guess_at end
    from jsonb_array_elements(p_senses) i
   where s.id = (i ->> 'id')::uuid
     and (
       (s.cefr, s.cefr_source, s.cefr_list, s.cefr_reason_tr)
         is distinct from
       (nullif(i ->> 'cefr', ''), nullif(i ->> 'cefr_source', ''), nullif(i ->> 'cefr_list', ''),
        nullif(i ->> 'cefr_reason_tr', ''))
       or (i ? 'cefr_guess' and s.cefr_guess is distinct from nullif(i ->> 'cefr_guess', ''))
       or coalesce((i ->> 'guess_asked')::boolean, false)
     );
  get diagnostics v_senses = row_count;

  return jsonb_build_object('senses', v_senses, 'terms', v_terms);
end;
$$;

revoke all on function public.lexicon_set_levels(jsonb, jsonb) from public, anon, authenticated;
grant execute on function public.lexicon_set_levels(jsonb, jsonb) to service_role;

-- List entries still waiting for the Turkish-learner check (or checked for an older list
-- level), words the lexicon already has first, then the most frequent: [{lemma_norm, pos,
-- source, cefr}].
create or replace function public.ref_level_tr_pending(p_limit integer default 100)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'lemma_norm', x.lemma_norm, 'pos', x.pos, 'source', x.source, 'cefr', x.cefr)
    order by x.in_lexicon desc, x.zipf desc nulls last, x.lemma_norm, x.pos, x.source), '[]'::jsonb)
  from (
    select r.lemma_norm, r.pos, r.source, r.cefr,
           exists (select 1 from public.lexicon_terms t where t.lemma_norm = r.lemma_norm) as in_lexicon,
           f.zipf
    from public.ref_word_levels r
    left join public.ref_word_freq f on f.lemma_norm = r.lemma_norm
    where r.tr_checked_at is null or r.tr_base_cefr is distinct from r.cefr
    order by in_lexicon desc, f.zipf desc nulls last, r.lemma_norm, r.pos, r.source
    limit least(greatest(coalesce(p_limit, 100), 1), 1000)
  ) x
$$;

revoke all on function public.ref_level_tr_pending(integer) from public, anon, authenticated;
grant execute on function public.ref_level_tr_pending(integer) to service_role;

-- Stores Turkish-learner check results. p_items: [{lemma_norm, pos, source, base_cefr,
-- cefr (null = list level kept), reason (null when kept), model, prompt_version}]. A row whose
-- list level is no longer base_cefr is skipped. Returns the number of rows stored.
create or replace function public.ref_set_level_tr(p_items jsonb)
returns integer
language plpgsql
volatile
security invoker
set search_path = ''
as $$
declare
  v_count integer;
begin
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 1000 then
    raise exception 'at most 1000 items per call' using errcode = '22023';
  end if;
  update public.ref_word_levels r
     set tr_checked_at = now(),
         tr_base_cefr = i ->> 'base_cefr',
         tr_cefr = nullif(i ->> 'cefr', ''),
         tr_reason = case when nullif(i ->> 'cefr', '') is null then null else nullif(i ->> 'reason', '') end,
         tr_model = left(i ->> 'model', 100),
         tr_prompt_version = left(i ->> 'prompt_version', 40)
    from jsonb_array_elements(p_items) i
   where r.lemma_norm = i ->> 'lemma_norm'
     and r.pos = i ->> 'pos'
     and r.source = i ->> 'source'
     and r.cefr = i ->> 'base_cefr';
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

revoke all on function public.ref_set_level_tr(jsonb) from public, anon, authenticated;
grant execute on function public.ref_set_level_tr(jsonb) to service_role;

-- ---------------------------------------------------------------------------
-- system AI budget (level job and later system jobs), separate from users' budgets
-- ---------------------------------------------------------------------------

create table public.ai_system_usage (
  day date primary key,
  calls integer not null default 0 check (calls >= 0)
);

alter table public.ai_system_usage enable row level security;
revoke all on table public.ai_system_usage from anon, authenticated;
-- No policies: service role only.

-- Atomically takes p_cost calls from today's (UTC) system budget. Returns {allowed, used, limit}.
create or replace function public.ai_system_consume(p_limit integer, p_cost integer default 1)
returns jsonb
language plpgsql
volatile
security invoker
set search_path = ''
as $$
declare
  v_day date := (now() at time zone 'utc')::date;
  v_used integer;
begin
  if p_limit is null or p_cost is null or p_cost < 1 then
    raise exception 'invalid arguments' using errcode = '22023';
  end if;
  insert into public.ai_system_usage as u (day, calls)
  values (v_day, 0)
  on conflict (day) do nothing;
  update public.ai_system_usage
     set calls = calls + p_cost
   where day = v_day and calls + p_cost <= p_limit
  returning calls into v_used;
  if v_used is not null then
    return jsonb_build_object('allowed', true, 'used', v_used, 'limit', p_limit);
  end if;
  select calls into v_used from public.ai_system_usage where day = v_day;
  return jsonb_build_object('allowed', false, 'used', coalesce(v_used, 0), 'limit', p_limit);
end;
$$;

revoke all on function public.ai_system_consume(integer, integer) from public, anon, authenticated;
grant execute on function public.ai_system_consume(integer, integer) to service_role;

-- ---------------------------------------------------------------------------
-- notes.level_override (synced through the registry like every notes column)
-- ---------------------------------------------------------------------------

alter table public.notes
  add column level_override text check (level_override in ('A1', 'A2', 'B1', 'B2', 'C1', 'C2'));

-- ---------------------------------------------------------------------------
-- push: a column the payload does not carry keeps its server value
-- ---------------------------------------------------------------------------
-- An app version that does not know a column yet (a phone still on v0.2 İP1 has no
-- level_override) sends rows without it. Before, jsonb_populate_record turned the missing
-- key into null, so editing a note's tags there cleared the level the user had set on
-- another device. Now only columns present in the payload are updated; inserts are
-- unchanged (a missing key is null, as before).
create or replace function public._sync_upsert(p_table text, p_payload jsonb)
returns text
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_cols text;
  v_set text;
  v_conflict text;
  v_count integer;
begin
  select st.conflict_key into v_conflict from public.sync_tables st where st.name = p_table and not st.insert_only;
  if v_conflict is null then
    raise exception 'unknown table' using errcode = '22023';
  end if;

  select
    string_agg(format('%I', a.attname), ', ' order by a.attnum),
    string_agg(format('%1$I = case when $1 ? %1$L then excluded.%1$I else t.%1$I end', a.attname), ', ' order by a.attnum)
      filter (where a.attname not in ('id', 'user_id', 'created_at'))
  into v_cols, v_set
  from pg_catalog.pg_attribute a
  where a.attrelid = format('public.%I', p_table)::regclass
    and a.attnum > 0 and not a.attisdropped;

  execute format(
    'insert into public.%1$I as t (%2$s)
       select %2$s from jsonb_populate_record(null::public.%1$I, $1)
     on conflict %3$s do update set %4$s
       where t.hlc collate "C" < excluded.hlc collate "C"',
    p_table, v_cols, v_conflict, v_set)
  using p_payload;
  get diagnostics v_count = row_count;
  return case when v_count > 0 then 'applied' else 'stale' end;
end;
$$;

revoke all on function public._sync_upsert(text, jsonb) from public, anon;
grant execute on function public._sync_upsert(text, jsonb) to authenticated;
